 Q.append(rec(C,9,i,'A logarithmic family and a root-count boundary','Functions and inequalities','2.15','hard',True,rf'For $x>0$, let $h(x)=\ln x-\frac x{{{a}}}$. This question investigates the number of solutions to $h(x)=k$.',[P('Find the global maximum of h.',M(rf'$h\prime(x)=1/x-1/{a}$.'),A(rf'The sole stationary input is $x={a}$.'),R(rf'The derivative is positive on $(0,{a})$ and negative on $({a},\infty)$.'),A(rf'The maximum is $\ln {a}-1$.')),P('Classify the number of solutions for every real k.',R(r'$h(x)\to-\infty$ as $x\to0^+$ and as $x\to\infty$.'),A(rf'Two below $\ln {a}-1$, one at that level, and none above it.')),P(rf'When $k=\ln {a}-2$, find the larger root to three significant figures.',M(rf'Solve $\ln x-x/{a}=\ln {a}-2$ numerically on $x>{a}$.'),A(rf'$x={N(root)}$.'))],'Symbolic derivative and both end limits checked; larger root obtained by bracketing above the unique maximum and residual checked.',style='problem-solving',answer_diagram=plot(s.lambdify(x,f,'math'),(.1,8*a),(-5,max(1,mx+1)),points=[(a,mx,'maximum')],title='Shape and maximum of h')))
